Lemma nc_cell_val : forall minv maxv i, 0 <= minv <= 255 -> 0 <= maxv <= 255 -> 0 <= i <= 9 ->
  ext_val false 0 4
    (alu64 ALU_ADD
       (sext 64 (mul_div M_DIV (low32 (mul_div M_MUL (Z_to_bv 64 i)
                                        (sext 64 (alu32 ALU_SUB (low32 (ext_val true 0 4 (Z_to_bv 64 maxv))) (low32 (ext_val true 0 4 (Z_to_bv 64 minv)))))))
                               (low32 (Z_to_bv 64 9))))
       (ext_val true 0 4 (Z_to_bv 64 minv)))
  = Z_to_bv 64 (nc_val minv maxv i).
Proof.
